const num = (v) => v.split('.').map(Number);

function aceita(faixa, versao) {
  const [M, m, p] = num(faixa.slice(1));
  const [vM, vm, vp] = num(versao);
  const naoMenor = vM > M || (vM === M && (vm > m || (vm === m && vp >= p)));
  if (!naoMenor) return false;
  if (faixa[0] === '~') return vM === M && vm === m;
  if (M > 0) return vM === M;
  return vM === 0 && vm === m;
}

const publicadas = ['1.4.1', '1.4.2', '1.4.9', '1.5.0', '2.0.0'];
