function instala(comando, lock) {
  if (comando === 'ci') {
    if (!lock) return 'ERRO: npm ci exige lockfile';
    return lock;
  }
  if (comando === 'install') return lock ?? maisNova;
  if (comando === 'update') return maisNova;
}

console.log('npm ci, com lock:      ', instala('ci', '2.1.4'));
